// Embed the template files (packages/core/templates/<id>/**) into src/templates/files.generated.ts, so the registry works
// wherever core is bundled (the packaged desktop app, the CLI) without reading files next to the code at run time.
//
//   node scripts/gen-templates.mjs          write src/templates/files.generated.ts
//   node scripts/gen-templates.mjs --check  exit 1 when the committed file is stale
//
// The generated file is committed; templates.test.ts fails when it is out of date.
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const TEMPLATES = join(root, 'templates');
const OUT = join(root, 'src', 'templates', 'files.generated.ts');

function* walk(dir) {
  for (const name of readdirSync(dir).sort()) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) yield* walk(p);
    else yield p;
  }
}

export function generate() {
  const table = {};
  for (const id of readdirSync(TEMPLATES).sort()) {
    const dir = join(TEMPLATES, id);
    if (!statSync(dir).isDirectory()) continue;
    table[id] = {};
    for (const file of walk(dir)) table[id][relative(dir, file).split(sep).join('/')] = readFileSync(file, 'utf8');
  }
  return (
    '// GENERATED by scripts/gen-templates.mjs from packages/core/templates/. Do not edit: change the template files and\n' +
    '// run `node scripts/gen-templates.mjs` in packages/core.\n' +
    '\n' +
    '/** Template id -> repo-relative path -> file content (RATCHET.md still has its {{placeholders}}). */\n' +
    'export const TEMPLATE_FILES: Readonly<Record<string, Readonly<Record<string, string>>>> = ' +
    JSON.stringify(table, null, 2) +
    ';\n'
  );
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const next = generate();
  if (process.argv.includes('--check')) {
    if (!existsSync(OUT) || readFileSync(OUT, 'utf8') !== next) {
      console.error('src/templates/files.generated.ts is stale: run `node scripts/gen-templates.mjs` in packages/core');
      process.exit(1);
    }
  } else {
    writeFileSync(OUT, next);
  }
}
